/** Validate without advancing async input; the returned check validates each item when consumed. */
export function validateRequest(value: unknown): (item: unknown) => void {
  const errors: string[] = [];
  validate75(value, "request", errors);
  if (errors.length) throw new TypeError("Invalid elevenlabs TTS request" + ":\n" + errors.join("\n"));
  validate82(value, "request", errors);
  const accepts0 = errors.length === 0;
  errors.length = 0;
  validate83(value, "request", errors);
  const accepts1 = errors.length === 0;
  errors.length = 0;
  return (item: unknown): void => {
    const errors: string[] = [];
    if (accepts0) {
      const before = errors.length;
      validate80(item, "text item", errors);
      if (errors.length === before) return;
    }
    if (accepts1) {
      const before = errors.length;
      validate81(item, "text item", errors);
      if (errors.length === before) return;
    }
    if (!errors.length) errors.push("text item: streaming input is not supported by this request");
    throw new TypeError("Invalid elevenlabs TTS input item" + ":\n" + errors.join("\n"));
  };
}
